static const uint16_t boot_frame_count = 64u;
static const uint16_t boot_change_count = 3104u;
static const uint16_t boot_last_event_tick = 2229u;
static const uint16_t boot_end_tick = 2229u;

static uint16_t boot_tick = 0;
static uint16_t boot_frame_index = 0;
static uint16_t boot_change_index = 0;

void boot_init() {
    boot_tick = 0;
    boot_frame_index = 0;
    boot_change_index = 0;
    clear_led();
}

void boot_timer_event() {
    while (boot_frame_index < boot_frame_count && boot_frames[boot_frame_index].tick == boot_tick) {
        uint8_t count = boot_frames[boot_frame_index].count;
        for (uint8_t i = 0; i < count && boot_change_index < boot_change_count; ++i) {
            const boot_change_t change = boot_changes[boot_change_index++];
            novation_led(change.led, change.velocity);
        }
        ++boot_frame_index;
    }

    if (boot_tick >= boot_end_tick) {
        mode_switch(MODE_PERFORMANCE);
        return;
    }

    ++boot_tick;
}

void boot_surface_event(uint8_t type, uint8_t index, uint8_t value) { (void)type; (void)index; (void)value; }
void boot_midi_event(uint8_t port, uint8_t status, uint8_t d1, uint8_t d2) { (void)port; (void)status; (void)d1; (void)d2; }
void boot_aftertouch_event(uint8_t index, uint8_t value) { (void)index; (void)value; }
